fun handleAppendEntries(req: AppendEntries): AppendReply {
    if (req.term < currentTerm) return AppendReply(currentTerm, false, 0)       // a deposed leader
    if (req.prevLogIndex > lastLogIndex || termAt(req.prevLogIndex) != req.prevLogTerm)
        return AppendReply(currentTerm, false, 0)                              // logs differ before these entries
    var index = req.prevLogIndex
    for (e in req.entries) {
        index++
        if (index <= lastLogIndex) {
            if (termAt(index) == e.term) continue                              // already have it
            while (log.size >= index) log.removeAt(log.size - 1)               // conflict: cut here
        }
        log += e
    }
    val lastNew = req.prevLogIndex + req.entries.size
    if (req.leaderCommit > commitIndex) commitIndex = maxOf(commitIndex, minOf(req.leaderCommit, lastNew))
    return AppendReply(currentTerm, true, lastNew)
}
